CAT = "afspGeneral"; SEG = "GEN"
# AFTR outline 2.13 to 2.16: digital assets, AMT (Rev. Proc. 2025-32 4.10), QBI (4.26 and 2.12),
# kiddie tax (4.02), 529 and ABLE (4.34), student loan discharge (IRC 108(f)(5)), NOL, premium tax
# credit (FS-2025-10), fringe benefits (4.15, 4.16, Rev. Proc. 2025-19), withholding and estimated
# tax, refunds, due dates and extensions, failure to file (4.52). Tax year 2026.
_qbi = min(40000 * 20 // 100, 60000 * 20 // 100); assert _qbi == 8000
_kid = 2 * 1350; assert _kid == 2700
_hsa = 4400 + 1000; assert _hsa == 5400
_ftf = min(535, 300); assert _ftf == 300

Q = [
("Starting with digital asset sales in 2025, brokers report gross proceeds to customers on:",
 "Form 1099-DA", ["Form 1099-B", "Form 1099-K", "Form 1099-MISC"],
 "Form 1099-DA, Digital Asset Proceeds From Broker Transactions, reports sales of digital assets by brokers. Gains and losses still go on Form 8949 and Schedule D."),
("A web designer is paid in cryptocurrency for a 2026 project. The payment is:",
 "Income at its fair market value", ["Taxed only when sold", "A nontaxable property swap", "Income at its later sale price"],
 "Digital assets received for services are ordinary income equal to their fair market value when received, and that value becomes the basis for a later sale (IRS digital assets guidance)."),
("For 2026, the alternative minimum tax exemption for a single filer, before any phaseout, is:",
 "$90,100", ["$88,100", "$140,200", "$70,100"],
 "Rev. Proc. 2025-32 (section 4.10) gives 2026 exemptions of $90,100 for unmarried filers, $140,200 joint and $70,100 married filing separately. The single phaseout starts at $500,000."),
("Under the 2025 law, from 2026 a taxpayer who materially participates and has at least $1,000 of qualified business income gets a QBI deduction of at least:",
 "$400", ["$1,000", "$200", "$500"],
 "OBBBA section 70105 adds a minimum QBI deduction of $400 for taxpayers with at least $1,000 of QBI from active trades or businesses, starting in 2026 (Rev. Proc. 2025-32, section 2.12)."),
("A sole proprietor below the threshold has $40,000 of qualified business income and $60,000 of taxable income before the deduction. Her QBI deduction is:",
 f"${_qbi:,}", ["$12,000", "$4,000", "$10,000"],
 "The deduction is the smaller of 20% of QBI ($8,000) or 20% of taxable income before the deduction, less net capital gain ($12,000), so $8,000 (Form 8995)."),
("For 2026, a child's net unearned income is taxed at the parent's rate to the extent it exceeds:",
 f"${_kid:,}", ["$1,350", "$2,600", "$13,500"],
 "The first $1,350 is offset by the child's standard deduction and the next $1,350 is taxed at the child's rate (Rev. Proc. 2025-32, section 4.02). Unearned income above $2,700 is taxed at the parent's rate on Form 8615."),
("For 2026, parents may report a child's interest and dividends on Form 8814 only if the child's gross income is under:",
 "$13,500", ["$2,700", "$12,500", "$10,000"],
 "The parent's election is open when the child's gross income is more than $1,350 and less than $13,500, ten times $1,350, and consists only of interest and dividends, including capital gain distributions (Rev. Proc. 2025-32, section 4.02)."),
("For 2026, the annual limit on contributions to one ABLE account from all sources, before any working-beneficiary extra, is:",
 "$20,000", ["$19,000", "$15,000", "$7,500"],
 "Rev. Proc. 2025-32 (section 4.34) sets the 2026 ABLE limit at $20,000, now indexed separately from the $19,000 gift exclusion (OBBBA section 70115)."),
("In 2026, a federal student loan is discharged because the borrower became totally and permanently disabled. The discharged amount is:",
 "Excluded from income", ["Taxable as ordinary income", "Taxable over $10,000", "Taxed as a capital gain"],
 "IRC 108(f)(5), made permanent by the 2025 law, excludes student loan discharges on account of death or total and permanent disability. Other forgiveness may be taxable unless another exclusion applies (Form 1099-C)."),
("An individual's net operating loss from 2024 is used on the 2026 return. The NOL deduction is limited to:",
 "80% of taxable income", ["100% of taxable income", "$3,000 a year", "The past two years' income"],
 "NOLs arising after 2017 generally cannot be carried back and carry forward indefinitely, but each year's deduction is limited to 80% of taxable income figured without it (Pub. 536)."),
("A family's 2026 advance premium tax credit payments were $4,000 more than the credit allowed. On the 2026 return they repay:",
 "The full $4,000", ["Up to a capped amount", "Half of the excess", "Nothing if income is low"],
 "For tax years after 2025, the repayment caps on excess advance payments no longer apply, so the whole difference is added to tax due or taken from the refund (FS-2025-10)."),
("To reconcile advance premium tax credit payments on Form 8962, the taxpayer uses information from:",
 "Form 1095-A", ["Form 1095-B", "Form 1095-C", "Form 1099-SA"],
 "Form 1095-A, Health Insurance Marketplace Statement, shows premiums, the benchmark plan and advance payments. Forms 1095-B and 1095-C report other coverage and employer offers."),
("For 2026, an employee can put at most how much into a health flexible spending arrangement through salary reduction?",
 "$3,400", ["$3,300", "$4,400", "$680"],
 "Rev. Proc. 2025-32 (section 4.15) sets the 2026 health FSA salary reduction limit at $3,400. If the plan allows a carryover, up to $680 of unused amounts can roll to the next year."),
("For 2026, the monthly limit on excludable qualified parking provided by an employer is:",
 "$340", ["$325", "$300", "$680"],
 "Rev. Proc. 2025-32 (section 4.16) sets both the 2026 transit pass and qualified parking exclusions at $340 a month."),
("A 56-year-old with self-only HDHP coverage for all of 2026 can contribute at most how much to an HSA?",
 f"${_hsa:,}", ["$4,400", "$8,750", "$5,500"],
 "The 2026 self-only limit is $4,400 (Rev. Proc. 2025-19), plus a $1,000 catch-up for account owners 55 or older (IRC 223(b)(3)): $5,400."),
("A taxpayer's 2025 AGI was $200,000. To avoid the 2026 estimated tax penalty, her 2026 payments can equal:",
 "110% of her 2025 tax", ["100% of her 2025 tax", "90% of her 2025 tax", "80% of her 2026 tax"],
 "The prior-year safe harbor rises from 100% to 110% of last year's tax when last year's AGI was over $150,000 ($75,000 married filing separately) (Form 1040-ES)."),
("For a calendar-year individual, the fourth 2026 estimated tax payment is due:",
 "January 15, 2027", ["December 31, 2026", "December 15, 2026", "April 15, 2027"],
 "Individual estimated payments for 2026 are due April 15, June 15 and September 15, 2026 and January 15, 2027 (Form 1040-ES)."),
("A taxpayer wants her refund split between a checking account and a savings account. She uses:",
 "Form 8888", ["Form 8879", "Form 9465", "Form 8822"],
 "Form 8888, Allocation of Refund, splits a direct deposit among up to three accounts. Form 9465 requests an installment agreement; Form 8822 changes an address."),
("A taxpayer files Form 4868 for 2026 but has a balance due. The extension:",
 "Gives time to file, not to pay", ["Gives time to file and pay", "Waives all late penalties", "Lasts until December 31"],
 "Form 4868 extends the filing date to October 15, 2027, but tax is still due April 15, 2027. Interest and the late payment penalty run on any unpaid tax."),
("A 2026 return showing $300 of unpaid tax is filed 90 days late with no extension. The failure to file penalty is at least:",
 f"${_ftf:,}", ["$535", "$45", "$75"],
 "For returns required to be filed in 2027 that are more than 60 days late, the minimum penalty is the smaller of $535 or 100% of the unpaid tax (Rev. Proc. 2025-32, section 4.52), so $300 here."),
]
